select case when s.rating >= 3.9 then 'high' when s.rating >= 2.6 then 'mid' else 'low' end as rating_bucket, count(*) as row_count, sum(ss.units) as total_units from store_sales ss inner join products p on ss.product_id = p.id left join suppliers s on p.supplier_id = s.id group by case when s.rating >= 3.9 then 'high' when s.rating >= 2.6 then 'mid' else 'low' end order by row_count desc;
